  1→//! Cache command implementation.
  2→//!
  3→//! Provides `bivvy cache list`, `bivvy cache clear`, etc.
  4→
  5→use anyhow::Result;
  6→use clap::{Args, Subcommand};
  7→
  8→use crate::cache::{default_cache_dir, format_duration, CacheStore, CacheValidator};
  9→use crate::ui::{Prompt, PromptResult, PromptType, UserInterface};
 10→
 11→use super::dispatcher::{Command, CommandResult};
 12→
 13→/// Arguments for the cache command.
 14→#[derive(Debug, Clone, Args)]
 15→pub struct CacheArgs {
 16→    #[command(subcommand)]
 17→    pub command: CacheSubcommand,
 18→}
 19→
 20→/// Cache subcommands.
 21→#[derive(Debug, Clone, Subcommand)]
 22→pub enum CacheSubcommand {
 23→    /// List cached entries.
 24→    List {
 25→        /// Show detailed information.
 26→        #[arg(long)]
 27→        verbose: bool,
 28→        /// Output as JSON.
 29→        #[arg(long)]
 30→        json: bool,
 31→    },
 32→    /// Clear the cache.
 33→    Clear {
 34→        /// Only clear expired entries.
 35→        #[arg(long)]
 36→        expired: bool,
 37→        /// Don't prompt for confirmation.
 38→        #[arg(short, long)]
 39→        force: bool,
 40→    },
 41→    /// Show cache statistics.
 42→    Stats,
 43→}
 44→
 45→/// The cache command implementation.
 46→pub struct CacheCommand {
 47→    args: CacheArgs,
 48→}
 49→
 50→impl CacheCommand {
 51→    /// Create a new cache command.
 52→    pub fn new(args: CacheArgs) -> Self {
 53→        Self { args }
 54→    }
 55→}
 56→
 57→impl Command for CacheCommand {
 58→    fn execute(&self, ui: &mut dyn UserInterface) -> crate::error::Result<CommandResult> {
 59→        let cache_dir = default_cache_dir();
 60→        let store = CacheStore::new(&cache_dir);
 61→
 62→        let exit_code = match &self.args.command {
 63→            CacheSubcommand::List { verbose, json } => list_cache(&store, *verbose, *json, ui)?,
 64→            CacheSubcommand::Clear { expired, force } => clear_cache(&store, *expired, *force, ui)?,
 65→            CacheSubcommand::Stats => show_stats(&store, ui)?,
 66→        };
 67→
 68→        Ok(if exit_code == 0 {
 69→            CommandResult::success()
 70→        } else {
 71→            CommandResult::failure(exit_code)
 72→        })
 73→    }
 74→}
 75→
 76→fn list_cache(
 77→    store: &CacheStore,
 78→    verbose: bool,
 79→    json: bool,
 80→    ui: &mut dyn UserInterface,
 81→) -> Result<i32> {
 82→    let entries = store.list()?;
 83→
 84→    if entries.is_empty() {
 85→        ui.message("Cache is empty");
 86→        return Ok(0);
 87→    }
 88→
 89→    if json {
 90→        let output = serde_json::to_string_pretty(&entries)?;
 91→        ui.message(&output);
 92→        return Ok(0);
 93→    }
 94→
 95→    ui.message(&format!("{} cached entries:\n", entries.len()));
 96→
 97→    for entry in entries {
 98→        let status = if entry.is_expired() {
 99→            "expired"
100→        } else {
101→            "fresh"
102→        };
103→        let remaining = entry.metadata.remaining_ttl();
104→        let ttl_str = if remaining > 0 {
105→            format_duration(chrono::Duration::seconds(remaining))
106→        } else {
107→            "expired".to_string()
108→        };
109→
110→        if verbose {
111→            ui.message(&format!("  {} ({})", entry.template_name, entry.source_id));
112→            ui.message(&format!("    Status: {}", status));
113→            ui.message(&format!("    TTL: {}", ttl_str));
114→            ui.message(&format!("    Size: {} bytes", entry.metadata.size_bytes));
115→            if let Some(etag) = &entry.metadata.etag {
116→                ui.message(&format!("    ETag: {}", etag));
117→            }
118→            if let Some(sha) = &entry.metadata.commit_sha {
119→                ui.message(&format!("    Commit: {}", sha));
120→            }
121→            ui.message("");
122→        } else {
123→            ui.message(&format!(
124→                "  {} [{}] {}",
125→                entry.template_name, status, ttl_str
126→            ));
127→        }
128→    }
129→
130→    Ok(0)
131→}
132→
133→fn clear_cache(
134→    store: &CacheStore,
135→    expired_only: bool,
136→    force: bool,
137→    ui: &mut dyn UserInterface,
138→) -> Result<i32> {
139→    if expired_only {
140→        let validator = CacheValidator::new(store);
141→        let removed = validator.cleanup_expired()?;
142→        ui.success(&format!("Cleared {} expired entries", removed));
143→        return Ok(0);
144→    }
145→
146→    let entries = store.list()?;
147→    if entries.is_empty() {
148→        ui.message("Cache is already empty");
149→        return Ok(0);
150→    }
151→
152→    let count = entries.len();
153→    if !force && ui.is_interactive() {
154→        let prompt = Prompt {
155→            key: "clear_cache".to_string(),
156→            question: format!("Clear {} cached entries?", count),
157→            prompt_type: PromptType::Confirm,
158→            default: Some("false".to_string()),
159→        };
160→
161→        match ui.prompt(&prompt)? {
162→            PromptResult::Bool(true) => {}
163→            _ => {
164→                ui.message("Cancelled");
165→                return Ok(0);
166→            }
167→        }
168→    }
169→
170→    let cleared = store.clear()?;
171→    ui.success(&format!("Cleared {} entries", cleared));
172→
173→    Ok(0)
174→}
175→
176→fn show_stats(store: &CacheStore, ui: &mut dyn UserInterface) -> Result<i32> {
177→    let entries = store.list()?;
178→    let total_size = store.total_size()?;
179→    let expired_count = entries.iter().filter(|e| e.is_expired()).count();
180→    let fresh_count = entries.len() - expired_count;
181→
182→    ui.message("Cache Statistics:\n");
183→    ui.message(&format!("  Total entries: {}", entries.len()));
184→    ui.message(&format!("  Fresh: {}", fresh_count));
185→    ui.message(&format!("  Expired: {}", expired_count));
186→    ui.message(&format!("  Total size: {} bytes", total_size));
187→    ui.message(&format!("  Location: {}", store.root().display()));
188→
189→    Ok(0)
190→}
