133→#[cfg(test)]
134→mod tests {
135→    use super::*;
136→    use std::sync::Mutex;
137→    use tempfile::TempDir;
138→
139→    // Mutex to serialize tests that use state path override
140→    static TEST_MUTEX: Mutex<()> = Mutex::new(());
141→
142→    fn with_temp_state<F, R>(f: F) -> R
143→    where
144→        F: FnOnce() -> R,
145→    {
146→        let _guard = TEST_MUTEX.lock().unwrap();
147→        let temp = TempDir::new().unwrap();
148→        let state_path = temp.path().join("resume-state.json");
149→        ResumeState::set_state_path_override(Some(state_path));
150→        let result = f();
