  1→//! Auto-update prompting and execution.
  2→
  3→use anyhow::Result;
  4→use std::process::Command;
  5→
  6→use super::{check_for_updates, detect_install_method, InstallMethod, UpdateInfo};
  7→use crate::ui::{Prompt, PromptResult, PromptType, UserInterface};
  8→
  9→/// Check for updates and prompt user if update available.
 10→///
 11→/// Returns true if an update was executed.
 12→pub fn check_and_prompt_update(ui: &mut dyn UserInterface) -> Result<bool> {
 13→    // Only check in interactive mode
 14→    if !ui.is_interactive() {
 15→        return Ok(false);
 16→    }
 17→
 18→    // Check for updates
 19→    let info = match check_for_updates() {
 20→        Some(info) => info,
 21→        None => return Ok(false),
 22→    };
 23→
 24→    // No update available
 25→    if !info.update_available {
 26→        return Ok(false);
 27→    }
 28→
 29→    // Detect install method
 30→    let method = detect_install_method();
 31→
 32→    // Prompt for update
 33→    if prompt_for_update(ui, &info, &method)? {
 34→        execute_update(&method)?;
 35→        return Ok(true);
 36→    }
 37→
 38→    Ok(false)
 39→}
 40→
 41→/// Prompt the user to update.
 42→fn prompt_for_update(
 43→    ui: &mut dyn UserInterface,
 44→    info: &UpdateInfo,
 45→    method: &InstallMethod,
 46→) -> Result<bool> {
 47→    ui.message(&format!(
 48→        "A new version of bivvy is available: {} -> {}",
 49→        info.current, info.latest
 50→    ));
 51→
 52→    if !method.supports_auto_update() {
 53→        if let Some(url) = &info.release_url {
 54→            ui.message(&format!("Download from: {}", url));
 55→        }
 56→        return Ok(false);
 57→    }
 58→
 59→    let prompt = Prompt {
 60→        key: "update_bivvy".to_string(),
 61→        question: "Would you like to update now?".to_string(),
 62→        prompt_type: PromptType::Confirm,
 63→        default: Some("true".to_string()),
 64→    };
 65→
 66→    match ui.prompt(&prompt)? {
 67→        PromptResult::Bool(confirmed) => Ok(confirmed),
 68→        _ => Ok(false),
 69→    }
 70→}
 71→
 72→/// Execute the update using the appropriate method.
 73→fn execute_update(method: &InstallMethod) -> Result<()> {
 74→    let command = method
 75→        .update_command()
 76→        .ok_or_else(|| anyhow::anyhow!("No update command for install method"))?;
 77→
 78→    let parts: Vec<&str> = command.split_whitespace().collect();
 79→    if parts.is_empty() {
 80→        anyhow::bail!("Empty update command");
 81→    }
 82→
 83→    let status = Command::new(parts[0]).args(&parts[1..]).status()?;
 84→
 85→    if !status.success() {
 86→        anyhow::bail!("Update command failed with exit code: {:?}", status.code());
 87→    }
 88→
 89→    Ok(())
 90→}
 91→
 92→/// Show update notification without prompting.
 93→pub fn show_update_notification(ui: &mut dyn UserInterface) {
 94→    if let Some(info) = check_for_updates() {
 95→        if info.update_available {
 96→            ui.message(&format!(
 97→                "Update available: {} -> {} (run `bivvy update` to upgrade)",
 98→                info.current, info.latest
 99→            ));
100→        }
101→    }
102→}
103→
104→/// Suppress update notification for the current session.
105→pub fn suppress_notification() {
106→    // This could use a session marker file or environment variable
107→    std::env::set_var("BIVVY_SUPPRESS_UPDATE", "1");
108→}
109→
110→/// Check if update notification is suppressed.
111→pub fn is_notification_suppressed() -> bool {
112→    std::env::var("BIVVY_SUPPRESS_UPDATE").is_ok()
113→}
