        let result = list_feedback(&store, None, None, false, &mut ui).unwrap();
        assert_eq!(result, 0);
    }

    #[test]
    fn list_feedback_with_entries() {
        let temp = TempDir::new().unwrap();
        let store = create_test_store(&temp);
        let mut ui = MockUI::new();

