    #[test]
    fn feedback_args_parsing() {
        use clap::Parser;

        #[derive(Parser)]
        struct TestCli {
            #[command(flatten)]
            feedback: FeedbackArgs,
        }

        let cli = TestCli::parse_from(["test", "--tag", "ux,perf", "some", "feedback"]);
        assert_eq!(cli.feedback.tag, vec!["ux", "perf"]);
        assert_eq!(cli.feedback.message, vec!["some", "feedback"]);
