  1→//! Command dispatching.
  2→//!
  3→//! This module provides the core command infrastructure:
  4→//! - [`Command`] trait for implementing commands
  5→//! - [`CommandResult`] for uniform result reporting
  6→//! - [`CommandDispatcher`] for routing CLI subcommands
  7→
  8→use std::path::{Path, PathBuf};
  9→
 10→use crate::cli::args::{Cli, Commands};
 11→use crate::error::Result;
 12→use crate::ui::UserInterface;
 13→
 14→/// Trait for command implementations.
 15→///
 16→/// Each CLI subcommand implements this trait to provide its execution logic.
 17→pub trait Command {
 18→    /// Execute the command.
 19→    ///
 20→    /// # Arguments
 21→    ///
 22→    /// * `ui` - User interface for displaying output and prompts
 23→    ///
 24→    /// # Returns
 25→    ///
 26→    /// A [`CommandResult`] indicating success/failure and exit code.
 27→    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult>;
 28→}
 29→
 30→/// Result of command execution.
 31→#[derive(Debug)]
 32→pub struct CommandResult {
 33→    /// Whether the command succeeded.
 34→    pub success: bool,
 35→
 36→    /// Exit code to use (0 for success, non-zero for failure).
 37→    pub exit_code: i32,
 38→}
 39→
 40→impl CommandResult {
 41→    /// Create a successful result.
 42→    pub fn success() -> Self {
 43→        Self {
 44→            success: true,
 45→            exit_code: 0,
 46→        }
 47→    }
 48→
 49→    /// Create a failure result.
 50→    pub fn failure(exit_code: i32) -> Self {
 51→        Self {
 52→            success: false,
 53→            exit_code,
 54→        }
 55→    }
 56→}
 57→
 58→/// Dispatches CLI commands to their implementations.
 59→pub struct CommandDispatcher {
 60→    project_root: PathBuf,
 61→}
 62→
 63→impl CommandDispatcher {
 64→    /// Create a new dispatcher for the given project root.
 65→    pub fn new(project_root: PathBuf) -> Self {
 66→        Self { project_root }
 67→    }
 68→
 69→    /// Get the project root path.
 70→    pub fn project_root(&self) -> &Path {
 71→        &self.project_root
 72→    }
 73→
 74→    /// Dispatch and execute a command.
 75→    ///
 76→    /// Routes the CLI subcommand to the appropriate command implementation
 77→    /// and executes it.
 78→    pub fn dispatch(&self, cli: &Cli, ui: &mut dyn UserInterface) -> Result<CommandResult> {
 79→        match &cli.command {
 80→            Some(Commands::Run(args)) => {
 81→                let cmd = super::run::RunCommand::new(&self.project_root, args.clone());
 82→                cmd.execute(ui)
 83→            }
 84→            Some(Commands::Init(args)) => {
 85→                let cmd = super::init::InitCommand::new(&self.project_root, args.clone());
 86→                cmd.execute(ui)
 87→            }
 88→            Some(Commands::Status(args)) => {
 89→                let cmd = super::status::StatusCommand::new(&self.project_root, args.clone());
 90→                cmd.execute(ui)
 91→            }
 92→            Some(Commands::List(args)) => {
 93→                let cmd = super::list::ListCommand::new(&self.project_root, args.clone());
 94→                cmd.execute(ui)
 95→            }
