 561→    fn depth_limit_enforced() {
 562→        let server = MockServer::start();
 563→
 564→        // Create a chain that's deeper than max_depth (set to 2)
 565→        // depth3 extends nothing
 566→        let depth3_yaml = "app_name: depth3\n";
 567→        // depth2 extends depth3
 568→        let depth2_yaml = format!(
 569→            "extends:\n  - url: {}\napp_name: depth2\n",
 570→            server.url("/depth3.yml")
 571→        );
 572→        // depth1 extends depth2
 573→        let depth1_yaml = format!(
 574→            "extends:\n  - url: {}\napp_name: depth1\n",
 575→            server.url("/depth2.yml")
 576→        );
 577→
 578→        server.mock(|when, then| {
 579→            when.method(GET).path("/depth3.yml");
 580→            then.status(200).body(depth3_yaml);
 581→        });
 582→        server.mock(|when, then| {
 583→            when.method(GET).path("/depth2.yml");
 584→            then.status(200).body(depth2_yaml);
 585→        });
 586→        server.mock(|when, then| {
 587→            when.method(GET).path("/depth1.yml");
 588→            then.status(200).body(depth1_yaml);
 589→        });
 590→
 591→        let config = BivvyConfig {
 592→            extends: Some(vec![ExtendsConfig {
 593→                url: server.url("/depth1.yml"),
 594→            }]),
 595→            ..Default::default()
 596→        };
 597→
 598→        // Use max_depth=2, chain is deeper
 599→        let temp = TempDir::new().unwrap();
 600→        let cache_dir = temp.keep().join("cache");
 601→        let fetcher = RemoteFetcher::with_cache_dir(Duration::from_secs(10), cache_dir);
 602→        let resolver = ExtendsResolver {
 603→            fetcher,
 604→            max_depth: 2,
 605→        };
 606→
 607→        let result = resolver.resolve(&config);
 608→
 609→        assert!(result.is_err());
 610→        let err = result.unwrap_err().to_string();
 611→        assert!(
 612→            err.contains("depth exceeds"),
 613→            "Error should mention depth: {}",
 614→            err
 615→        );
 616→    }
